pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address caller, uint256 value) public {
        vm.assume(caller != address(0) && caller != address(c) && caller != address(0xdead));
        vm.assume(value >= 0 && value <= type(uint256).max);

        // Give caller some balance so burn can succeed
        vm.deal(caller, 1 ether);

        address deployer = address(this);
        vm.prank(caller);
        try c.burn(value) returns (bool) {
            // after successful burn, owner should still be deployer
            assertTrue(c.owner() == deployer);
        } catch {
            // if burn reverts (e.g., insufficient balance), owner should still be deployer
            assertTrue(c.owner() == deployer);
        }
    }
}

