pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 initialSupply, string memory tokenName, string memory tokenSymbol, address caller, uint256 burnAmount) public {
        // Deploy a fresh contract with given parameters
        c = new C(initialSupply, tokenName, tokenSymbol);
        // Ensure caller is not the owner to trigger onlyOwner revert
        vm.assume(caller != c.owner());
        // Record totalSupply before burn
        uint256 supplyBefore = c.totalSupply();
        // Attempt to call burn as non-owner (should revert)
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", burnAmount));
        // Assert that the call reverted
        assertTrue(!success);
        // Assert that totalSupply remains unchanged after failed burn
        assertTrue(c.totalSupply() == supplyBefore);
    }
}

