pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 initialSupply, uint256 mintAmount, uint256 burnAmount, address target, address to) public {
        // Restrict inputs to valid ranges
        vm.assume(initialSupply <= 1000000);
        vm.assume(mintAmount <= 1000);
        vm.assume(burnAmount <= mintAmount + initialSupply); // burn cannot exceed what can exist
        vm.assume(target != address(0));
        vm.assume(to != address(0));

        // Deploy with initial supply
        c = new C(initialSupply, "", "");

        // Mint some tokens
        c.mintToken(target, mintAmount);

        // Transfer some tokens to another account (optional, to have balance at 'to')
        if (c.balanceOf(address(this)) >= 1) {
            c.transfer(to, 1);
        }

        // Perform burn
        (bool successBurn, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", burnAmount));

        // General rule: totalSupply >= sum of all balances? but simpler: after burn, totalSupply should be non-negative
        assertTrue(successBurn || burnAmount == 0);
    }
}

