pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 burnAmount, address target, uint256 mintAmount) public {
        vm.assume(mintAmount > 0 && mintAmount < type(uint256).max / 2);
        vm.assume(burnAmount < type(uint256).max / 2);

        // Mint some tokens to target
        c.mintToken(target, mintAmount);

        // Transfer tokens from owner (deployer) to target to give target a balance
        // (owner has initial supply = 0, so this is skipped)

        // Now burn from target's balance (but target may not be owner, so use prank)
        vm.prank(target);
        (bool successBurn, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", burnAmount));

        // After burn, the total supply should equal the sum of all balances
        // Since we only have one account (owner) with non-zero balance, check
        // totalSupply >= balanceOf[owner] (the only place minted tokens can be)
        // Because the bug subtracts mintedAmount from totalSupply, totalSupply can become less than balanceOf[owner].
        bool invariant = c.totalSupply() >= c.balanceOf(address(this));
        assertTrue(invariant);
    }
}

