pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address caller, uint256 burnAmount, uint256 initialBalance) public {
        vm.assume(caller != address(0));
        vm.assume(initialBalance >= burnAmount);
        vm.assume(burnAmount > 0);

        // Setup initial balance for the caller
        vm.prank(caller);
        c.mintToken(caller, initialBalance);

        // Record balance before burn
        uint256 balanceBefore = c.balanceOf(caller);

        // Perform burn
        vm.prank(caller);
        // c.transferOwnership would be needed if onlyOwner modifier applies; but burn is onlyOwner
        // Since caller is not owner, we need to make caller the owner first
        vm.prank(c.owner());
        c.transferOwnership(caller);

        vm.prank(caller);
        c.burn(burnAmount);

        // Check: balance after should equal balance before minus burnAmount
        uint256 balanceAfter = c.balanceOf(caller);
        assertTrue(balanceAfter == balanceBefore - burnAmount);
    }
}

