pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        amount = bound(amount, 0, type(uint256).max);
        vm.prank(caller);
        c.mintToken(caller, 1000 ether);
        uint256 balanceBefore = c.balanceOf(caller);
        uint256 totalSupplyBefore = c.totalSupply();
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", amount));
        if (success) {
            assertTrue(c.balanceOf(caller) == balanceBefore - amount, "caller balance decreased by amount");
            assertTrue(c.totalSupply() == totalSupplyBefore - amount, "totalSupply decreased by amount");
        } else {
            assertTrue(c.balanceOf(caller) == balanceBefore, "caller balance unchanged on revert");
            assertTrue(c.totalSupply() == totalSupplyBefore, "totalSupply unchanged on revert");
        }
    }
}

