pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 _value) public {
        vm.assume(_value <= 1e18);
        // Get sum of all balances before burn (only the owner has balance)
        uint256 sumBefore = c.balanceOf(address(this));
        // Call burn
        (bool success,) = address(c).call(abi.encodeWithSignature("burn(uint256)", _value));
        // If burn succeeded, total supply decreased but balanceOf(msg.sender) should also decrease
        if (success) {
            // After burn, the caller's balance should have decreased by _value
            // But in the bug, balanceOf does not decrease, so totalSupply != sum of balances
            uint256 sumAfter = c.balanceOf(address(this));
            assertTrue(sumAfter + _value == sumBefore);
        } else {
            // If burn reverted, everything unchanged
            uint256 sumAfter = c.balanceOf(address(this));
            assertTrue(sumAfter == sumBefore);
        }
    }
}

