pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address caller, uint256 initialSupply, uint256 _value) public {
        vm.assume(caller != address(0));
        vm.assume(initialSupply > 0 && initialSupply <= type(uint256).max);
        vm.assume(_value > 0 && _value <= initialSupply);
        // Deploy with initialSupply
        c = new C(initialSupply, "", "");
        // Give caller some tokens via mintToken
        vm.prank(c.owner());
        c.mintToken(caller, initialSupply);
        // Record balance before burn
        uint256 balanceBefore = c.balanceOf(caller);
        // Attempt burn as caller
        vm.prank(caller);
        try c.burn(_value) {
            // If burn completes, check the invariant
            uint256 balanceAfter = c.balanceOf(caller);
            assertTrue(balanceAfter == balanceBefore - _value, "Balance invariant violated");
        } catch {
            // Revert case: ignore
        }
    }
}

