pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 initialSupply, uint256 mintAmount, uint256 burnAmount) public {
        // Restrict inputs to avoid overflows and ensure meaningful state
        vm.assume(initialSupply <= 1e30);
        vm.assume(mintAmount <= 1e30);
        vm.assume(burnAmount <= 1e30);
        vm.assume(mintAmount + initialSupply <= type(uint256).max / 1e18);
        // Deploy with initial supply
        c = new C(initialSupply, "", "");
        // Mint tokens to the caller (msg.sender is address(this) by default)
        c.mintToken(address(this), mintAmount);
        // Record totalSupply before burn
        uint256 supplyBefore = c.totalSupply();
        // Burn some tokens
        (bool ok,) = address(c).call(abi.encodeWithSignature("burn(uint256)", burnAmount));
        if (ok) {
            // Handle success: burn succeeded only if balance >= burnAmount
            uint256 supplyAfter = c.totalSupply();
            bool supplyDecreased = supplyAfter < supplyBefore;
            bool burnPositive = burnAmount > 0;
            // General rule: supply decreases if and only if burn amount > 0
            assertTrue(supplyDecreased == burnPositive);
        } else {
            // Burn reverted: totalSupply must be unchanged
            uint256 supplyAfter = c.totalSupply();
            assertTrue(supplyAfter == supplyBefore);
        }
    }
}

