pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 initialSupply, string memory tokenName, string memory tokenSymbol, address target, uint256 mintedAmount, uint256 burnAmount) public {
        // Ensure mintedAmount and burnAmount are reasonable
        vm.assume(mintedAmount > 0 && mintedAmount < 1e30);
        vm.assume(burnAmount > 0 && burnAmount < 1e30);
        // Deploy with given parameters (use limited values to avoid huge numbers)
        c = new C(initialSupply % 1000, tokenName, tokenSymbol);
        uint256 totalSupplyAfterMint;
        // Perform a mint
        c.mintToken(target, mintedAmount);
        // Then burn some tokens
        c.burn(burnAmount);
        // After mint and burn, totalSupply should be >= initialSupply (since mint adds to supply, and burn only reduces but never below initial if minted amount >= burned)
        uint256 totalSupply = c.totalSupply();
        // The invariant: totalSupply after mint + burn should be >= initial supply (since mint adds, burn subtracts, but totalSupply should never go below the original if burn is not excessive)
        // However, due to the bug, totalSupply might be less than initial supply after mint + burn.
        // So the rule: totalSupply >= initialSupply * 10**18 (since decimals=0)
        assertTrue(totalSupply >= initialSupply * 10**uint256(c.decimals()) / 10**uint256(c.decimals()));
    }
}

